/** Generated by scripts/optimize-images.mjs before each production build. */
export function imageSrcset(path: string): string {
  const match = path.match(/^\/images\/(?!optimized\/)(.+)\.(jpe?g|png|webp|avif)$/i);
  if (!match) return '';
  const base = `/images/optimized/${match[1]}`;
  return [480, 960, 1440].map(w => `${base}-${w}.webp ${w}w`).join(', ');
}
